    // Total task factories across all runPool calls = 4 (2 per group)
    expect(mockRunPool).toHaveBeenCalledTimes(2);
    const totalTasks = (
      mockRunPool.mock.calls as [readonly TaskFactory<void>[], PoolOptions][]
    ).reduce((sum, call) => sum + call[0].length, 0);
