        const signal = new AbortController().signal;
        for (const task of tasks) {
          try {
            const value = await task(signal);
            results.push({ status: 'fulfilled', value });
          } catch (reason) {
            results.push({ status: 'rejected', reason });
          }
        }
        return results;
      }
