import { getBuiltinSkillContent } from '../index';

// -- Constants --

const EXPECTED_SKILL_KEYS = [
  'reasoning-coach',
  'translator',
  'concise-writer',
  'eli5-explainer',
] as const;

const ALL_LOCALES: readonly Locale[] = ['hu', 'en'] as const;

