      });

      expect(stuckAtOldest).toBe(true);
      expect(result.current.currentEntry).toBe('repeated');
    });

    it('should cap history at 50 entries', () => {
      const { result } = renderHook(() => useInputHistory(''));

      act(() => {
        for (let i = 0; i < 55; i++) {
