      systemPrompts: [],
      model: '',
      providerId: '',
      sourceSessionId: '',
    });

    // Assert: putLabRun was called to persist the new tab immediately.
    // FAILS against current impl because openScratchTab defers persistence via _pendingScratch.
    expect(putLabRun).toHaveBeenCalled();
