  const fakeTx: FakeTx = {
    objectStore: vi.fn((name: string) => stores[name] ?? defaultStore()),
  };

  const fakeDb: FakeDb = {
    transaction: vi.fn().mockReturnValue(fakeTx),
  };

  return { fakeDb, fakeTx, stores };
};

