    const abortIdx = callLog.indexOf('abort');
    const putIdx = callLog.indexOf('putLabRun');
    expect(abortIdx).toBeGreaterThanOrEqual(0);
    expect(putIdx).toBeGreaterThanOrEqual(0);
    expect(abortIdx).toBeLessThan(putIdx);
