import { useSessionStore } from '@/features/sessions';
import { buildModelMetadataRows } from '@/features/settings';
import { useTranslation } from '@/i18n';
import { resolveModelParams } from '@/lib/model-params';
import type { Model } from '@/services/llm/types';

export interface ChatModelDetailsProps {
  readonly supportsThinking: boolean;
  readonly thinkingEnabled: boolean;
  readonly onThinkingToggle: () => void;
  readonly rows: readonly { readonly label: string; readonly value: string }[];
  readonly title: string;
  readonly triggerLabel: string;
  readonly thinkingLabel: string;
  readonly jsonLabel: string;
}

export function useChatModelDetails(activeModel: Model | undefined): ChatModelDetailsProps {
  const t = useTranslation();
  const activeSessionId = useSessionStore(s => s.activeSessionId);
  const sessionList = useSessionStore(s => s.sessionList);
  const setSessionModelParams = useSessionStore(s => s.setSessionModelParams);

  const activeSession = sessionList.find(s => s.id === activeSessionId);
  const thinkingEnabled = activeSession?.modelParams?.thinkingEnabled === true;

  const onThinkingToggle = (): void => {
    if (!activeSessionId) return;
    const resolved = resolveModelParams(activeSession?.modelParams);
    void setSessionModelParams(activeSessionId, { ...resolved, thinkingEnabled: !thinkingEnabled });
  };

  const rows = activeModel
    ? buildModelMetadataRows(activeModel, {
        context: t('settings.modelInfo.context'),
        pricing: t('settings.modelInfo.pricing'),
        modalities: t('settings.modelInfo.modalities'),
        thinking: t('settings.modelInfo.thinking'),
        thinkingValue: t('settings.modelInfo.thinkingValue'),
      })
    : [];

  return {
    supportsThinking: activeModel?.supportsThinking === true,
    thinkingEnabled,
    onThinkingToggle,
    rows,
    title: t('settings.modelInfo.title'),
    triggerLabel: t('settings.modelInfo.triggerLabel'),
    thinkingLabel: t('settings.modelInfo.thinkingToggleLabel'),
    jsonLabel: t('settings.modelInfo.jsonLabel'),
  };
}


// ==== corpus/features/chat/hooks/useInputHistory.ts ====
import { useCallback, useRef, useState } from 'react';

const MAX_ENTRIES = 50;

export interface InputHistoryState {
  readonly isNavigating: boolean;
  readonly currentEntry: string | null;
}

export interface InputHistoryActions {
  readonly navigateUp: (textarea: HTMLTextAreaElement) => boolean;
  readonly navigateDown: (textarea: HTMLTextAreaElement) => boolean;
  readonly dismiss: () => void;
  readonly addEntry: (content: string) => void;
  readonly reset: (entries?: readonly string[]) => void;
}

export interface UseInputHistoryReturn extends InputHistoryState, InputHistoryActions {}

function isCursorOnFirstLine(textarea: HTMLTextAreaElement): boolean {
  return !textarea.value.slice(0, textarea.selectionStart).includes('\n');
}

export function useInputHistory(currentDraft: string): UseInputHistoryReturn {
  const entriesRef = useRef<readonly string[]>([]);
  const draftRef = useRef<string>('');
  const indexRef = useRef<number>(-1);
  const currentDraftRef = useRef<string>(currentDraft);
  currentDraftRef.current = currentDraft;

  const [isNavigating, setIsNavigating] = useState(false);
  const [currentEntry, setCurrentEntry] = useState<string | null>(null);

  const navigateUp = useCallback((textarea: HTMLTextAreaElement): boolean => {
    if (!isCursorOnFirstLine(textarea)) return false;
    if (entriesRef.current.length === 0) return false;

    if (indexRef.current === -1) {
      draftRef.current = currentDraftRef.current;
      const newIndex = entriesRef.current.length - 1;
      indexRef.current = newIndex;
      setIsNavigating(true);
      setCurrentEntry(entriesRef.current[newIndex] ?? null);
      return true;
    }

    if (indexRef.current > 0) {
      const newIndex = indexRef.current - 1;
      indexRef.current = newIndex;
      setCurrentEntry(entriesRef.current[newIndex] ?? null);
    }

    return true;
  }, []);

  const navigateDown = useCallback((textarea: HTMLTextAreaElement): boolean => {
    if (indexRef.current === -1) return false;
    if (!isCursorOnFirstLine(textarea)) return false;

    if (indexRef.current < entriesRef.current.length - 1) {
      const newIndex = indexRef.current + 1;
      indexRef.current = newIndex;
      setCurrentEntry(entriesRef.current[newIndex] ?? null);
      return true;
    }

    indexRef.current = -1;
    setIsNavigating(false);
    setCurrentEntry(null);
    return true;
  }, []);

  const dismiss = useCallback((): void => {
    if (indexRef.current === -1) return;
    indexRef.current = -1;
    setIsNavigating(false);
    setCurrentEntry(null);
  }, []);

  const addEntry = useCallback((content: string): void => {
    const entries = entriesRef.current;
    if (entries.length > 0 && entries[entries.length - 1] === content) return;

    const updated = [...entries, content];
    entriesRef.current =
      updated.length > MAX_ENTRIES ? updated.slice(updated.length - MAX_ENTRIES) : updated;

    indexRef.current = -1;
    setIsNavigating(false);
    setCurrentEntry(null);
  }, []);

  const reset = useCallback((newEntries?: readonly string[]): void => {
    entriesRef.current = newEntries ? [...newEntries] : [];
    indexRef.current = -1;
    setIsNavigating(false);
    setCurrentEntry(null);
  }, []);

  return {
    isNavigating,
    currentEntry,
    navigateUp,
    navigateDown,
    dismiss,
    addEntry,
    reset,
  };
}


// ==== corpus/features/chat/hooks/useScrollToBottom.ts ====
import { useEffect, useRef } from 'react';

export function useScrollToBottom<T extends HTMLElement>(
  _dependency: unknown
): React.RefObject<T | null> {
  const bottomRef = useRef<T | null>(null);

  // useEffect: dom-imperative — scrolls bottom sentinel into view on mount
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  return bottomRef;
}


